      SUBROUTINE THORSC---- CALCULATES SINGLE INTEGRALS FOR THIRD-ORDER MATRIX ELEMENTSC---- FOR A COMBINED FUNCTION BENDING MAGNETC----------------------------------------------------------------------      INCLUDE 'ELM0B.CIN'      INCLUDE 'ELM4A.CIN'      INCLUDE 'ELM4D.CIN'      INCLUDE 'HSINT.CIN'      INCLUDE 'HSINT3.CIN'      INCLUDE 'HSLINT.CIN'      INCLUDE 'HSLIN3.CIN'      INCLUDE 'HPINT.CIN'      INCLUDE 'HPINT3.CIN'      INCLUDE 'HPLINT.CIN'      INCLUDE 'HPLIN3.CIN'      INCLUDE 'H0F.CIN'      INCLUDE 'H02F.CIN'      INCLUDE 'H03F.CIN'      INCLUDE 'H04F.CIN'      INCLUDE 'H0L.CIN'      INCLUDE 'H0P.CIN'      INCLUDE 'H02L.CIN'      INCLUDE 'H03L.CIN'      INCLUDE 'H04L.CIN'      INCLUDE 'H05L.CIN'      INCLUDE 'H06L.CIN'      INCLUDE 'H07L.CIN'      INCLUDE 'H08L.CIN'      INCLUDE 'H0N.CIN'      INCLUDE 'H0T.CIN'      INCLUDE 'H0W.CIN'      INCLUDE 'H02W.CIN'      INCLUDE 'H03W.CIN'      INCLUDE 'H04W.CIN'      INCLUDE 'H0WF.CIN'      INCLUDE 'H02WF.CIN'      INCLUDE 'H03WF.CIN'      INCLUDE 'H04WF.CIN'      INCLUDE 'H0WT.CIN'      INCLUDE 'LP.CIN'      INCLUDE 'TERMS.CIN'      INCLUDE 'VSINT3.CIN'      INCLUDE 'VSLIN3.CIN'      INCLUDE 'VPINT3.CIN'      INCLUDE 'VPLIN3.CIN'      INCLUDE 'WMN.CIN'      INCLUDE 'WM2N.CIN'      INCLUDE 'WM5N.CIN'C--------------------------------------------------------------------      REAL            HPL3, HPL4, HSL3, HSL4      REAL            SMLCY, SNARKC      IF (XPND .OR. NB .EQ. 0.0) SNARK = 2.0/3.0*L3 - 2./15.*NB*H02L5      IF (.NOT. XPND .AND. NB .NE. 0.0)     1 SNARK = (L - CY*SY)/H02NC      IF (XPND) THEN        HSL3 = 0.05*H05L5 - WMN*H07L7/840.        HSL4 = 1.0/30.0*H06L6 - WMN*H08L8/1680.      ELSE        HSL3 = 6.0*(SX - L) + H02L3        HSL4 = 24.0*(1.0 - 0.5*H02L2 + 1.0/24.0*H04L4     1   - CX)      ENDIF      HSLCX = - 0.25*SMLCX/H02W + 0.25*SX*L2      HSLSX =  0.25*SMLCX*L/WMN      IF (XPND) THEN        HSLCC0 = 1./6.*L3 - 7./120.*WMN*H02L5        HSLCS0 = 1.0/12.0*L4 - 0.025*WMN*H02L6        HSLCD0 = 0.025*H0L5 - 19./2520.*WMN*H03L7        HSLSS0 = 0.05*L5 - 23./2520.*WMN*H02L7        HSLSD0 = 1.0/60.0*H0L6 - 17./6720.*WMN*H03L8        HSLCC2 = 1.0/6.0*L3 - (0.05*NB + WMN/120.)*H02L5        HSLCS2 = 1.0/12.0*L4 - (NB/45. + WMN/360.)*H02L6        HSLSS2 = 0.05*L5 - (NB/126. + WMN/840.)*H02L7      ELSE        HSLCC0 = 1./3.*L/H02W + 4./9.*CX*SX/H02W     1   - 7./9.*SX/H02W + 1./3.*SX**2*L        HSLCS0 = - 1./3.*CX*SX*L/H02W     1   + 4./9.*SX**2/H02W - 2./9.*DISP/H03W        HSLCD0 = - 1./3.*L/H03W2 + 0.25*CX*L/H03W2     1   - 4./9.*CX*SX/H03W2 + 0.25*SX*L2/H0W     2   + 19./36.*SX/H03W2 - 1./3.*SX**2*L/H0W        HSLSS0 = 2./3.*L/H04W2 - 4./9.*CX*SX/H04W2     1   - 2./9.*SX/H04W2 - 1./3.*SX**2*L/H02W        HSLSD0 = - 0.25*CX*L2/H03W2     1   + 1./3.*CX*SX*L/H03W2     2   + 0.25*SX*L/H03W2 - 4./9.*SX**2/H03W2     3   + 2./9.*DISP/H04W2        HSLCC2 = 0.5*(1.0/WMN + 1.0/WM5N)*L/H02     1   - (2.*NB/WM5N2 + 0.5*WMN/WM5N2 + 0.5/WMN)*SX/H02     2   + 4.*NB*CY*SY/H02F2 - NB*SY**2*L/WM5N        HSLCS2 = - 2.*WMN*DISN/H02F2     1   + CY*SY*L/H02F + 4.*NB*SY**2/H02F2        HSLSS2 = - 2.0*L/H04WF     1   + 4.0*(1.0-3*NB)*SX/H04WF2     2   + 2.*SX/H04F2 - 4.*CY*SY/H04F2     3   + SY**2*L/H02F      ENDIFC      HSCCC0 = 0.125*CX*SX**2 + 0.375*SX*L      IF (XPND) THEN        HSCCS0 = 1.0/6.0*L3 - 1./15.*WMN*H02L5        HSCCD0 = 1.0/24.0*H0*L4 - 7./360.*WMN*H03L6        HSCSS0 = 1.0/12.0*L4 - 11./360.*WMN*H02L6        HSCSD0 = 0.025*H0L5 - 1./105.*WMN*H03L7        HSCDD0 = 1.0/120.0*H02L6 - 1./320.*WMN*H04L8      ELSE        HSCCS0 = - 0.125*CX*L/H02W     1   + 0.125*SX/H02W + 0.125*SX**3        HSCCD0 = 1./3.*DISP/H02W - 0.125*CX*SX**2/H0W     1   - 0.375*SX*L/H0W + 1./3.*SX**2/H0W        HSCSS0 = - 0.125*CX*SX**2/H02W + 0.125*SX*L/H02W        HSCSD0 = 0.125*CX*L/H03W2 - 1./3.*CX*SX/H03W2     1   + 5./24.*SX/H03W2 - 0.125*SX**3/H0W        HSCDD0 = - 2./3.*DISP/H03W2     1   + 0.125*CX*SX**2/H02W2 + 0.875*SX*L/H02W2     2   - 2./3.*SX**2/H02W2      ENDIF      IF (XPND) THEN        HSSSS0 = 0.05*L5 - 11./840.*WMN*H02L7        HSSSD0 = 1.0/60.0*H0L6 - 9./2240.*WMN*H03L8        HSSDD0 = 1.0/168.0*H02L7 - 5./4032.*WMN*H04L9        HSDDD0 = 1.0/448.0*H03L8 - 1./2688.*WMN*H05L10      ELSE        HSSSS0 = 0.375*SMLCX/H04W2 -  0.125*SX**3/H02W        HSSSD0 = 2./3.*DISP/H04W2     1   + 0.125*CX*SX**2/H03W2 - 0.125*SX*L/H03W2     2   - 1./3.*SX**2/H03W2        HSSDD0 = - 0.625*CX*L/H04W3     1   + 2./3.*CX*SX/H04W3 - 1./24.*SX/H04W3     2   + 0.125*SX**3/H02W2        HSDDD0 = 2.0*DISP/H04W3     1   - 0.125*CX*SX**2/H03W3 - 1.875*SX*L/H03W3     2   + SX**2/H03W3      ENDIF      HSCCC2 = - 0.25*NB*CX*SY**2/WM2N + 0.25*SX*L     1 + 0.25*WMN*SX*CY*SY/WM2N      IF (XPND) THEN        HSCCS2 = 1.0/6.0*L3 - 1./30.*H02L5        HSCSS2 = 1.0/12.0*L4 - (NB/90. + 7./360.*WMN)*H02L6      ELSE        HSCCS2 = 0.25*CX*CY*SY/H02T + 0.25*WMN*SX*SY**2/WM2N     1   - 0.25*SX/H02T        HSCSS2 = 0.25*CX*SY**2/H02T + 0.25*SX*SNARK     1   - 0.25*SX*CY*SY/H02T      ENDIFC      IF (XPND) THEN        HSSCC2 = 1.0/6.0*L3 - (NB/20. + WMN/60.)*H02L5        HSSCS2 = 1.0/12.0*L4 - (NB/45. + WMN/120.)*H02L6        HSSSS2 = 0.05*L5 - (NB/126. + 13./2520.*WMN)*H02L7      ELSE        HSSCC2 = - 0.25*CX*L/H02W     2   - 0.25*CX*CY*SY/H02T     3   - 0.25*NB*SX*SY**2/WM2N     4   + 0.25*SX*(1.0/WMN + 1.0/WM2N)/H02        HSSCS2 = - 0.25*CX*SY**2/H02T     1   + 0.25*SX*CY*SY/H02T        HSSSS2 = - 0.25*CX*SNARK/H02W     1   - 0.25*(SX - CX*CY*SY)/H04WT     2   + 0.25*SX*SY**2/H02T      ENDIF      IF (XPND) THEN        HSDCC2 = 1.0/24.0*H0*L4 - (NB/60. + WMN/360.)*H03L6        HSDCS2 = 0.025*H0L5 - (NB/126. + WMN/630.)*H03L7        HSDSS2 = 1.0/60.0*H0L6 - (NB/336. + WMN/960.)*H03L8      ELSE        HSDCC2 = 0.5*DISP*(1.0/WMN + 1.0/WM5N)/H02     1   + 0.25*NB*CX*SY**2/H0WT - 0.25*SX*L/H0W     3   - 0.25*SX*CY*SY/H0T - NB*SY**2/H0WF        HSDCS2 = - 0.25*CX*CY*SY/H03WT - SX/H03WF     1   - 0.25*SX*SY**2/H0T + 0.25*SX/H03WT     2   + CY*SY/H03WF        HSDSS2 = - 0.25*CX*SY**2/H03WT     1   - 2.0*DISP/H04WF - 0.25*SX*SNARK/H0W     3   + 0.25*SX*CY*SY/H03WT + SY**2/H03WF      ENDIFC      IF (XPND) THEN        HPL3 = 0.25*WMN*L4 - WMN2*H02L6/120.        HPL4 = 0.2*WMN2*L5 - WMN3*H02L7/210.      ELSE        HPL3 = - 6.0*DISP/H03 + 3.0*L2/H02        HPL4 = 24.0*(SX - L + 1.0/6.0*WMN*H02L3)/H04      ENDIF      HPLCX = 0.25*CX*L2 + 0.25*SX*L      IF (XPND) THEN        HPLSX = L3/3.0 - 0.05*WMN*H02L5      ELSE        HPLSX = 0.25*SX/H02W - 0.25*CX*L/H02W     1   + 0.25*SX*L2      ENDIF      HPLCC0 = 7./9.*DISP/H0 + 2./3.*CX*SX*L - 5./9.*SX**2      IF (XPND) THEN        HPLCS0 = 1.0/3.0*L3 - .15*WMN*H02L5        HPLCD0 = 0.125*H0*L4 - 19./360.*WMN*H03L6        HPLSS0 = 0.25*L4 - 23./360.*WMN*H02L6        HPLSD0 = 0.1*H0L5 - 17./840.*WMN*H03L7        HPLCC2 = 0.5*L2 - (0.25*NB + WMN/24.)*H02L4        HPLCS2 = 1.0/3.0*L3 - (2./15.*NB + WMN/60.)*H02L5        HPLSS2 = 0.25*L4 - (1./18.*NB + WMN/120.)*H02L6      ELSE        HPLCS0 = - 1./3.*L/H02W + 5./9.*CX*SX/H02W     1   - 2./9.*SX/H02W + 2./3.*SX**2*L        HPLCD0 = 0.25*CX*L2/H0W     1   - 2./3.*CX*SX*L/H0W + 0.25*SX*L/H0W     2   + 5./9.*SX**2/H0W - 7./9.*DISP/H02W        HPLSS0 = - 2./3.*CX*SX*L/H02W     1   +  5./9.*SX**2/H02W + 2./9.*DISP/H03W        HPLSD0 = 1./3.*L/H03W2 - 0.25*CX*L/H03W2     1   - 5./9.*CX*SX/H03W2 + 0.25*SX*L2/H0W     2   + 17./36.*SX/H03W2 - 2./3.*SX**2*L/H0W        HPLCC2 = ((2.*NB + 0.5*WMN)/WM5N2 + 0.5/WMN)*(1.0 - CX)/H02     1   - 2.*NB*CY*SY*L/WM5N - NB*(WMN + 4.*NB)*SY**2/WM5N2        HPLCS2 = L/H02F - 2.*WMN*SX/H02F2     1   + (4.*NB + WMN)*CY*SY/H02F2     2   - 2.*NB*SY**2*L/WM5N        HPLSS2 = - 2.0*(2.0*(1.0-3.0*NB) + WMN)*DISP/H03F2     1   + 2.*CY*SY*L/H02F     2   + (4.*NB + WMN)*SY**2/H02F2      ENDIFC      HPCCC0 = 0.375*CX*L + 0.625*SX - 0.375*WMN*H02*SX**3      HPCCS0 = 0.375*CX*SX**2 + 0.125*SX*L      IF (XPND) THEN        HPCCD0 = 1.0/6.0*H0*L3 - 7./60.*WMN*H03L5        HPCSS0 = 1.0/3.0*L3 - 11./60.*WMN*H02L5        HPCSD0 = 0.125*H0*L4 - 1./15.*WMN*H03L6        HPCDD0 = 0.05*H02L5 - 0.025*WMN*H04L7      ELSE        HPCCD0 = - 0.375*CX*L/H0W + 2./3.*CX*SX/H0W     1   - 7./24.*SX/H0W + 0.375*SX**3*H0        HPCSS0 = 0.125*CX*L/H02W     1   - 0.125*SX/H02W + 0.375*SX**3        HPCSD0 = - 1./3.*DISP/H02W - 0.375*CX*SX**2/H0W     1   - 0.125*SX*L/H0W + 2./3.*SX**2/H0W        HPCDD0 = 0.875*CX*L/H02W2     1   - 4./3.*CX*SX/H02W2 + 11./24.*SX/H02W2     2   - 0.375*SX**3/WMN      ENDIFC      IF (XPND) THEN        HPSSS0 = 0.25*L4 - 11./120.*WMN*H02L6        HPSSD0 = 0.1*H0L5 - 9./280.*WMN*H03L7        HPSDD0 = 1.0/24.0*H02L6 - 5./448.*WMN*H04L8        HPDDD0 = 1.0/56.0*H03L7 - 5./1344.*WMN*H05L9      ELSE        HPSSS0 = - 0.375*CX*SX**2/H02W     1   + 0.375*SX*L/H02W        HPSSD0 = - 0.125*CX*L/H03W2     1   - 2./3.*CX*SX/H03W2 + 19./24.*SX/H03W2     2   - 0.375*SX**3/H0W        HPSDD0 = 2./3.*DISP/H03W2     1   + 0.375*CX*SX**2/H02W2 + 0.625*SX*L/H02W2     2   - 4./3.*SX**2/H02W2        HPDDD0 = - 1.875*CX*L/H03W3     1   + 2.*CX*SX/H03W3 - 0.125*SX/H03W3     2   + 0.375*SX**3/H0W2      ENDIFC      HPCCC2 = 0.25*CX*L + 0.25*(1.0 - NB/WM2N)*CX*CY*SY     1 + 0.25*(1.0 + WMN/WM2N)*SX - 0.25*NB*WMN*H02*SX*SY**2/WM2N      IF (XPND) THEN        HPCCS2 = 0.5*L2 - 1.0/6.0*H02L4        HPCSS2 = 1.0/3.0*L3 - (NB/15. + 7.0/60.0*WMN)*H02L5      ELSE        HPCCS2 = 0.25*(1.0 - NB/WM2N)*CX*SY**2 + 0.25*WMN*SX*CY*SY/WM2N        HPCSS2 = 0.25*CX*SNARK + 0.25*CX*CY*SY/H02T     1   + 0.25*WMN*SX*SY**2/WM2N - 0.25*SX/H02T      ENDIFC      HPSCC2 = 0.25*NB*CX*SY**2/WM2N + 0.25*SX*L     1 + 0.25*(1.0 - NB/WM2N)*SX*CY*SY      IF (XPND) THEN        HPSCS2 = 1.0/3.0*L3 - (2./15.*NB + 0.05*WMN)*H02L5        HPSSS2 = 0.25*L4 - (NB/18. + 13./360.*WMN)*H02L6      ELSE        HPSCS2 = - 0.25*CX*CY*SY/H02T     1   + 0.25*(1.0 - NB/WM2N)*SX*SY**2 + 0.25*SX/H02T        HPSSS2 = - 0.25*CX*SY**2/H02T + 0.25*SX*SNARK     1   + 0.25*SX*CY*SY/H02T      ENDIFC      IF (XPND) THEN        HPDCC2 = 1.0/6.0*H0*L3 - (0.1*NB + WMN/60.)*H03L5        HPDCS2 = 0.125*H0*L4 - (NB/18. + WMN/90.)*H03L6        HPDSS2 = 0.1*H0L5 - (NB/42. + WMN/120.)*H03L7      ELSE        HPDCC2 = - 0.25*CX*L/H0W     1   + 0.25*(NB/WM2N - 1.0)*CX*CY*SY/H0W     2   + 0.25*NB*H0*SX*SY**2/WM2N     3   + 0.25*(1.0/WMN - 1.0/WM2N + 2.0/WM5N)*SX/H0     4   - 2.*NB*CY*SY/H0WF        HPDCS2 = DISP/H02F     1   - 0.25*(1.0 - NB/WM2N)*CX*SY**2/H0W     2   - 0.25*SX*CY*SY/H0T - 2.*NB*SY**2/H0WF        HPDSS2 = - 0.25*CX*SNARK/H0W     1   - 0.25*CX*CY*SY/H03WT - 0.25*SX*SY**2/H0T     2   - 0.25*SX*(4.0/WMN + 3.0/WM2N)/H03F     3   + 2.*CY*SY/H03WF      ENDIFC      VSL3 = 0.05*L5      IF (XPND) THEN        VSL3CX = 0.05*L5 - (NB/840. + WMN/84.)*H02L7        VSL3SX = 1.0/30.0*L6 - (NB/1680. + WMN/336.)*H02L8      ELSE        VSL3CX = 6.0*L/H04 + 18.0*L*CX/H04 - 24.0*SX/H04     1   + 6.0*L2*SX/H02 - L3*CX/H02        VSL3SX = - L3*SX/H02 + 18.0*L*SX/H04 - 6.0*L2*CX/H04     1   + 24.0*(CX - 1.0)/H06      ENDIF      IF (NB .EQ. 0.0) SMLCY = L3/3.0      IF (NB .NE. 0.0) SMLCY = (SY - L*CY)/H02N      VSLCY = - 0.25*SMLCY + 0.25*SY*L2      VSLSY = 0.25*SMLCY*L      IF (XPND) THEN        VSLCC1 = 1.0/6.0*L3 - (NB/30 + WMN/40.)*H02L5        VSLCS1 = 1.0/12.0*L4 - (NB/120. + WMN/60.)*H02L6      ELSE        VSLCC1 = - (2.*NB + 0.5*WMN)*SY*(1.0 + CX)/H02F2     1   - 0.5*SY*DISP/H0 - CX*CY*L/H02F     2   + 2.*WMN*SX*CY/H02F2 - 2.0*NB*SX*SY*L/WM5N        VSLCS1 = - 2.0*(3.0 - 7.0*NB)*CY*DISP/H03F2     1   - CX*SY*L/H02F + 2.0*SX*CY*L/H02F     2   + 2.*WMN*SX*SY/H02F2      ENDIF      IF (XPND) THEN        VSLSC1 = 1.0/12.0*L4 - (7.*NB/360. + WMN/180.)*H02L6        VSLSS1 = 0.05*L5 - (13.*NB/2520 + WMN/252.)*H02L7        VSLDC1 = 0.025*H0L5 - (11./1680.*NB + WMN/1008.)*H03L7      ELSE        VSLSC1 = 2.*WMN*CY*DISP/H03F2     1   +  2.0*NB*CX*SY*L/H02WF - SX*CY*L/H02F     2   + ( - (2.*NB + 0.5*WMN)/WM5N2 + 0.5/WMN)*SX*SY/H02        VSLSS1 = - 2.*SY/H04F2 - 2.0*CX*CY*L/H04WF     1   - 2.*CX*SY/H04F2     2   + 2.0*(2.0*(1.0 - 3.0*NB)/WMN + 1.0)*SX*CY/H04F2     3   - SX*SY*L/H02F        VSLDC1 = - 0.25*SMLCY/H0W     1   + 0.25*SY*L2/H0W     2   + (2.*NB/WMN + 0.5)*SY*(1.0 + CX)/H03F2     3   + 0.5*SY*DISP/H02W + CX*CY*L/H03WF     4   - 2.*SX*CY/H03F2 + 2.0*NB*SX*SY*L/H0WF      ENDIF      IF (XPND) THEN        VSLDS1 = 1.0/60.0*H0L6 - (NB/560. + WMN/1344.)*H03L8      ELSE        VSLDS1 = 0.25*SMLCY*L/H0W     1   + 2.0*(2.0*(1.0 - 3.0*NB)/WMN + 1.0)*CY*DISP/H04F2     2   + CX*SY*L/H03WF - 2.0*SX*CY*L/H03WF     3   - 2.*SX*SY/H03F2      ENDIFC      VSCCC1 = - 0.25*NB*CX*SX*SY/WM2N + 0.25*SY*L     1 + 0.25*WMN*SX**2*CY/WM2N      IF (XPND) THEN        VSCCS1 = 1.0/6.0*L3 - (NB/60. + WMN/20.)*H02L5        VSCSC1 = 1.0/6.0*L3 - H02L5/30.        VSCSS1 = 1.0/12.0*L4 - (NB/120. + WMN/45.)*H02L6        VSCDC1 = 1.0/24.0*H0*L4 - 7.*H03L6/720.        VSCDS1 = 0.025*H0L5 - (13.*NB/5040. + WMN/144.)*H03L7      ELSE        VSCCS1 = 0.25*CX*SX*CY/H02T + 0.25*SMLCY     1   - 0.25*SY/H02T + 0.25*WMN*SX**2*SY/WM2N        VSCSC1 = - 0.25*CX*SX*CY/H02T + 0.25*SY/H02T     1   - 0.25*NB*SX**2*SY/WM2N        VSCSS1 = - 0.25*CX*SX*SY/H02T     1   + 0.25*SX**2*CY/H02T        VSCDC1 = CY*DISP/H02F - 0.25*SY*L/H0W     1   - 0.25*(1.0/WMN - 1.0/WM2N)*CX*SX*SY/H0     2   + 0.5*(1.0/WMN - 1.0/WM5N)*SX*SY/H0     3   - 0.25*SX**2*CY/H0T        VSCDS1 = - CX*SY/H03WF     1   - 0.25*CX*SX*CY/H03WT     2   - SY/H03WF + 0.25*SY/H03WT     3   - 0.25*SMLCY/H0W + 2.0*SX*CY/H03WF     4   - 0.25*SX**2*SY/H0T      ENDIFC      IF (XPND) THEN        VSSSC1 = 1.0/12.0*L4 - (7.*NB/360. + WMN/90.)*H02L6        VSSSS1 = 0.05*L5 - (13.*NB/2520. + WMN/126.)*H02L7        VSSDC1 = 0.025*H0L5 - (11.*NB/1680. + WMN/336.)*H03L7        VSSDS1 = 1.0/60.0*H0L6 - (NB/560. + WMN/448.)*H03L8      ELSE        VSSSC1 = - 0.25*(1.0/WMN - 1.0/WM2N)*CX*SX*SY/H02     1   + 0.25*SY*L/H02W - 0.25*SX**2*CY/H02T        VSSSS1 = - 0.25*CX*SX*CY/H04WT     1   + 0.25*SMLCY/H02W + 0.25*SY/H04WT     2   - 0.25*SX**2*SY/H02T        VSSDC1 = 0.5*(1.0/WM5N - 1.0/WMN)*CX*SY/H03W     1   + 0.25*CX*SX*CY/H03WT     2   + 0.5*(1.0/WMN + 1.0/WM5N)*SY/H03W     3   - 0.25*SY/H03WT - SX*CY/H03WF     4   + 0.25*(1.0/WM2N - 1.0/WMN)*SX**2*SY/H0        VSSDS1 = 2.0*CY*DISP/H04WF     1    + 0.25*CX*SX*SY/H03WT     2    - SX*SY/H03WF     3    - 0.25*SX**2*CY/H03WT      ENDIFC      IF (XPND) THEN        VSDDC1 = 1.0/120.0*H02L6 - (NB/420. + WMN/1344.)*H04L8        VSDDS1 = 1.0/168.0*H02L7 - (NB/1512. + WMN/1728.)*H04L9      ELSE        VSDDC1 = - 2.*CY*DISP/H03WF     1   + 0.25*(1.0/WMN - 1.0/WM2N)*CX*SX*SY/H02W     2   + 0.75*SY*L/H02W2     4   + (1.0/WM5N - 1.0/WMN)*SX*SY/H02W     5   + 0.25*SX**2*CY/H02WT        VSDDS1 = 2.*CX*SY/H04W2F     1   + 0.25*CX*SX*CY/H04W2T + 0.75*SMLCY/H02W2     2   + 2.*SY/H04W2F - 0.25*SY/H04W2T     3   - 4.0*SX*CY/H04W2F     4   + 0.25*SX**2*SY/H02WT      ENDIFC      VSCCC3 = 0.125*CY*SY**2 + 0.375*SY*L      VSCCS3 = 0.125*SMLCY + 0.125*SY**3      VSCSS3 = 0.125*SY*SNARKC      IF (XPND .OR. NB .EQ. 0.0) THEN        VSSSS3 = 0.05*L5 - 11.*NB*H02L7/840.      ELSE        VSSSS3 = (3.0*SMLCY - SY**3)/(8.0*NB*H02)      ENDIFC      VPL3 = 0.25*L4      IF (XPND) THEN        VPL3CX = 0.25*L4 - (NB/120. + WMN/12.)*H02L6        VPL3SX = 0.2*L5 - (NB/210. + WMN/42.)*H02L7      ELSE        VPL3CX = ((3.0*H02L2 - 6.0)*CX     1   + (H04L3 - 6.0*H02L)*SX + 6.0)/H04        VPL3SX = ((3.0*H02L2 - 6.0)*SX     1   - (H02L3 - 6.0*L)*CX)/H04      ENDIF      VPLCY = 0.25*CY*L2 + 0.25*SY*L      VPLSY = 0.25*SMLCY + 0.25*SY*L2      IF (XPND) THEN        VPLCC1 = 0.5*L2 - (NB/6. + WMN/8.)*H02L4        VPLCS1 = 1.0/3.0*L3 - (NB/20. + WMN/10.)*H02L5        VPLSC1 = 1.0/3.0*L3 - (7.*NB/60. + WMN/30.)*H02L5        VPLSS1 = 0.25*L4 - (13.*NB/360. + WMN/36.)*H02L6        VPLDC1 = 0.125*H0*L4 - (11.*NB/240. + WMN/144.)*H03L6        VPLDS1 = 0.1*H0L5 - (NB/70. + WMN/168.)*H03L7      ELSE        VPLCC1 =     1   - ((2.*NB + 0.5*WMN)/WM5N2 + 0.5/WMN)*CY*(1.0 - CX)/H02     2   - NB*CX*SY*L/WM5N + 0.5*(1.0 + WMN/WM5N)*SX*CY*L     3   + 2.*NB*WMN*SX*SY/WM5N2        VPLCS1 = ((2.*NB + 0.5*WMN)/WM5N2 - 0.5/WMN)*SY/H02     1   + ((2.*NB + 0.5*WMN)/WM5N2 + 0.5/WMN)*CX*SY/H02     2   + CX*CY*L/H02F - 2.*WMN*SX*CY/H02F2     3   + 0.5*(1.0 + WMN/WM5N)*SX*SY*L        VPLSC1 = - 2.*NB*SY/H02F2     1   - 0.5*(1.0/WMN + 1.0/WM5N)*CX*CY*L/H02     2   - 2.*NB*CX*SY/H02F2 - NB*SX*SY*L/WM5N     3   + ((2.*NB + 0.5*WMN)/WM5N2 + 0.5/WMN)*SX*CY/H02        VPLSS1 = - 2.0*WMN*CY*DISP/H03F2     1   - 0.5*(1.0/WMN + 1.0/WM5N)*CX*SY*L/H02     2   + SX*CY*L/H02F     3   + ((2.*NB + 0.5*WMN)/WM5N2 + 0.5/WMN)*SX*SY/H02        VPLDC1 = 0.25*CY*L2/H0W     1   + (2.*NB/(WMN*WM5N2) + 0.5/WMN2 + 0.5/WM5N2)*     2                 CY*(1.0 - CX)/H03     3   + 0.25*SY*L/H0W + NB*CX*SY*L/H0WF     4   -  0.5*(1.0/WMN + 1.0/WM5N)*SX*CY*L/H0     5   - 2.*NB*SX*SY/H0F2        VPLDS1 = 0.25*SMLCY/H0W     1 + 0.25*SY*L2/H0W     2 + (- 2.*NB/(WMN*WM5N2) + 0.5/WMN2 - 0.5/WM5N2)*SY/H03     3 - CX*CY*L/H03WF     4 + (- 2.*NB/(WMN*WM5N2) - 0.5/WMN2 - 0.5/WM5N2)*CX*SY/H03     5 + 2.*SX*CY/H03F2     6 - (0.5/WMN + 0.5/WM5N)*SX*SY*L/H0      ENDIFC      VPCCC1 = 0.25*(1.0 + WMN/WM2N)*CX*SX*CY + 0.25*CY*L     1 + 0.25*(1.0 - NB/WM2N)*SY     2 + 0.25*NB*WMN*SX**2*SY*H02/WM2N      VPCCS1 = 0.25*(1.0 + WMN/WM2N)*CX*SX*SY + 0.25*SY*L     2 - 0.25*WMN*SX**2*CY/WM2N      VPCSC1 = - 0.25*NB*CX*SX*SY/WM2N     1 + 0.25*(1.0 + WMN/WM2N)*SX**2*CY      IF (XPND) THEN        VPCSS1 = 1.0/3.0*L3 - (NB/20 + 2.*WMN/15)*H02L5        VPCDC1 = 1.0/6.0*H0*L3 - 7.*H03L5/120.        VPCDS1 = 0.125*H0*L4 - (13.*NB/720. + 7.*WMN/144.)*H03L6      ELSE        VPCSS1 = 0.25*CX*SX*CY/H02T - 0.25*SY/H02T     1   + 0.25*(1.0 + WMN/WM2N)*SX**2*SY        VPCDC1 = - NB*CX*SY/H0WF     1   - 0.25*(1.0/WMN + 1.0/WM2N)*CX*SX*CY/H0     2   - 0.25*CY*L/H0W - NB*SY/H0WF     3   + 0.25*(NB/WM2N - 1.0)*SY/H0W     4   + 0.5*(1.0/WMN + 1.0/WM5N)*SX*CY/H0     5   - 0.25*NB*SX**2*SY*H0/WM2N        VPCDS1 = - CY*DISP/H02F - 0.25*SY*L/H0W     1   - 0.25*(1.0/WMN + 1.0/WM2N)*CX*SX*SY/H0     2   + 0.5*(1.0/WMN + 1.0/WM5N)*SX*SY/H0     3   + 0.25*SX**2*CY/H0T      ENDIFC      IF (XPND) THEN        VPSSC1 = 1.0/3.0*L3 - (7.*NB/60. + WMN/15.)*H02L5        VPSSS1 = 0.25*L4 - (13.*NB/360. + WMN/18.)*H02L6        VPSDC1 = 0.125*H0*L4 - (11.*NB/240. + WMN/48.)*H03L6        VPSDS1 = 0.1*H0L5 - (NB/70. + WMN/56.)*H03L7      ELSE        VPSSC1 = 0.25*CY*L/H02W     1   + 0.25*(NB/WM2N + 1.0)*SY/H02W     2   - 0.25*(1.0/WMN + 1.0/WM2N)*CX*SX*CY/H02     4   - 0.25*NB*SX**2*SY/WM2N        VPSSS1 = - 0.25*(1.0/WMN + 1.0/WM2N)*CX*SX*SY/H02     1   + 0.25*SY*L/H02W + 0.25*SX**2*CY/H02T        VPSDC1 = 0.5*(1.0/WMN + 1.0/WM5N)*CY*DISP/H02     1   + 0.25*NB*CX*SX*SY/H0WT     3   - NB*SX*SY/H0WF     4   - 0.25*(1.0/WMN + 1.0/WM2N)*SX**2*CY/H0        VPSDS1 = - 0.5*(1.0/WMN + 1.0/WM5N)*CX*SY/H03W     1 - 0.25*CX*SX*CY/H03WT     2 + 0.5*(1.0/WMN - 1.0/WM5N)*SY/H03W     3 + 0.25*SY/H03WT + SX*CY/H03WF     5 - 0.25*(1.0/WMN + 1.0/WM2N)*SX**2*SY/H0      ENDIFC      IF (XPND) THEN        VPDDC1 = 0.05*H02L5 - (2.*NB/105. + WMN/168.)*H04L7        VPDDS1 = 1.0/24.0*H02L6 - (NB/168. + WMN/192.)*H04L8      ELSE        VPDDC1 = 2.*NB*CX*SY/H02W2F     1   + 0.25*(1.0/WMN + 1.0/WM2N)*CX*SX*CY/H02W     2   + 0.75*CY*L/H02W2 + 2.*NB*SY/H02W2F     3   + 0.25*(3.0 - NB/WM2N)*SY/H02W2     4   - (1.0/WMN + 1.0/WM5N)*SX*CY/H02W     5   + 0.25*NB*SX**2*SY/(WMN*WM2N)        VPDDS1 = 2.*CY*DISP/H03WF + 0.75*SY*L/H02W2     1   + 0.25*(1.0/WMN + 1.0/WM2N)*CX*SX*SY/H02W     2   - (1.0/WMN + 1.0/WM5N)*SX*SY/H02W     3   - 0.25*SX**2*CY/H02WT      ENDIFC      VPCCC3 = 0.375*CY*L + 0.625*SY - 0.375*NB*H02*SY**3      VPCCS3 = 0.375*CY*SY**2 + 0.125*SY*L      VPCSS3 = - 0.125*SMLCY + 0.375*SY**3      VPSSS3 =  0.375*SY*SNARK      RETURN      END